pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic: Harmonic-inspired Best-Fit with Lookahead Pressure
    // Objective: Minimize post_residual, but heavily penalize small "sliver" residuals 
    // that cannot accommodate typical future items.

    let mut score = post_residual as f64;

    // 1. Penalize slivers: Residuals < 10 are often "dead space" because min item size is 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead pressure: If the next item is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the bin because it 
    // forces a new bin later for that large item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0;
        } else {
            // Reward bins that maintain enough space for the next item
            score -= 10.0;
        }
    }

    // 3. Harmonic balance: Favor bins that align with common fractions of capacity 
    // to keep residuals useful for mid-sized items (e.g., 20, 25, 33).
    let harmonic_penalty = (post_residual % 25) as f64 * 0.5;
    score += harmonic_penalty;

    // 4. Efficiency scaling: As we approach the end of the stream, prioritize 
    // filling existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if we have options
        score += 40.0 * (1.0 - progress);
        // If we are forced to open a new bin, ensure it's not done prematurely
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 5. Mean residual equilibrium: Avoid creating outliers. 
    // Penalize bins that deviate significantly from the mean current utilization.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}

