pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. If this is a new bin, apply a significant penalty to encourage filling existing bins first.
    // We calibrate the penalty to be slightly higher than the worst possible fit (100) 
    // unless the number of open bins is already high (diminishing returns).
    if bin_residual == bin_capacity {
        score += 110.0 - (open_bins_count as f64 * 0.5);
    }

    // 2. Lookahead optimization: If next_item_size is known, penalize post_residual 
    // if it results in a "dead zone" (too small to fit the next item).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // This placement creates a gap that cannot fit the next known item.
            score += 40.0;
        } else {
            // This placement leaves space for the next item. Reward it.
            score -= 25.0;
        }
    }

    // 3. Mean residual balancing: Prefer bins that stay close to the current average 
    // to avoid creating extreme outliers (very empty or very full).
    let diff_from_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_from_mean * 0.2;

    // 4. Scarcity handling: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Progress-based scaling: As we approach the end of the stream, 
    // become more aggressive about filling gaps (lower tolerance for large residuals).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.3);

    score
}
